"""Migration of Meridian CRM rule ACC-004 credit-hold release validation."""

from decimal import Decimal
from typing import Any


class BusinessRuleViolation(Exception):
    """A legacy business-rule validation failure."""

    code: str
    message: str

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


def _legacy_number(value: Any) -> Decimal:
    """Apply legacy numeric coercion: empty or missing values are zero."""
    if value is None or value == "":
        return Decimal("0")
    return Decimal(str(value))


def release_credit_hold(account: dict) -> tuple[dict, list[dict]]:
    """Release an account credit hold while preserving legacy ACC-004 semantics."""
    updated_account = dict(account)

    # Legacy CHAR(1) booleans treat blank as N; only Y denotes an active hold.
    if account.get("CRED_HOLD", "") != "Y":
        return updated_account, []

    if _legacy_number(account.get("CRED_LIMIT", "")) <= Decimal("0"):
        raise BusinessRuleViolation(
            code="E1004",
            message="Cannot release credit hold with zero credit limit",
        )

    updated_account["CRED_HOLD"] = "N"
    audits = [{
        "code": "CRED_HOLD_OFF",
        "entity_id": account.get("ACCT_ID", ""),
    }]
    return updated_account, audits
